import logging
from contextlib import contextmanager

import wrapt

SHORT_FORMAT = "%(message)s"
SHORT_FORMATTER = logging.Formatter(SHORT_FORMAT, datefmt="%I:%M:%S")
LONG_FORMAT = "[%(levelname)7s] %(message)s"
LONG_FORMATTER = logging.Formatter(LONG_FORMAT, datefmt="%I:%M:%S")


@wrapt.decorator
def check_real_logger(wrapped, instance=None, args=None, kwargs=None):
    """Create instance of real_logger if it does not exist"""
    if args is None:
        args = ()
    if kwargs is None:
        kwargs = {}
    if logger.real_logger is None:
        logger.real_logger = create_real_logger()
        return wrapped(*args, **kwargs)
    else:
        return wrapped(*args, **kwargs)


def create_stream_handler(level, formatter):
    """Create a stream (standard output to console) handler with given logging level"""
    stream_handler = logging.StreamHandler()
    stream_handler.setLevel(level)
    stream_handler.setFormatter(formatter)
    return stream_handler


def create_real_logger():
    """Create a logger with one stream handler and two file handlers (one for INFO and one for DEBUG level)"""
    real_logger = logging.getLogger("taf.sw.reporting_portal")
    real_logger.setLevel(getattr(logging, "DEBUG"))
    if logger.handler:
        real_logger.addHandler(logger.handler)
    return real_logger


@contextmanager
def set_new_formatter_for_handlers(handlers):
    """Replace formatters for logging module handlers for execution time"""
    for handler in handlers:
        handler.setFormatter(SHORT_FORMATTER)
    try:
        yield
    finally:
        for handler in handlers:
            handler.setFormatter(LONG_FORMATTER)


class logger:
    handler = None
    real_logger = None

    @staticmethod
    def define_handler():
        """Function used to define stream handler"""
        logger.handler = create_stream_handler(
            getattr(logging, "DEBUG"), LONG_FORMATTER
        )

    @check_real_logger
    @staticmethod
    def info(msg, *args, **kwargs):
        """Log 'msg % args' with severity 'INFO'."""
        logger.real_logger.info(msg, *args, **kwargs)

    @check_real_logger
    @staticmethod
    def debug(msg, *args, **kwargs):
        """Log 'msg % args' with severity 'DEBUG'."""
        logger.real_logger.debug(msg, *args, **kwargs)

    @check_real_logger
    @staticmethod
    def warning(msg, *args, **kwargs):
        """Log 'msg % args' with severity 'WARNING'."""
        logger.real_logger.warning(msg, *args, **kwargs)

    @check_real_logger
    @staticmethod
    def error(msg, *args, **kwargs):
        """Log 'msg % args' with severity 'ERROR'."""
        logger.real_logger.error(msg, *args, **kwargs)

    @check_real_logger
    @staticmethod
    def status(msg, *args, **kwargs):
        """Log 'msg % args' without severity prefix"""
        with set_new_formatter_for_handlers(logger.real_logger.handlers):
            logger.real_logger.info(msg, *args, **kwargs)

    @check_real_logger
    @staticmethod
    def raw_info(msg, *args, **kwargs):
        """Log 'msg % args' without severity prefix and with additional indentation"""
        with set_new_formatter_for_handlers(logger.real_logger.handlers):
            logger.real_logger.info(" " * 10 + msg, *args, **kwargs)

    @check_real_logger
    @staticmethod
    def set_logger_level(level):
        """Set the level of logger.

        :param  string  level:   String that defines level of logging class.
        """
        logger.real_logger.setLevel(getattr(logging, level.upper()))

    @check_real_logger
    @staticmethod
    def type_of_error_info(exception, *args, **kwargs):
        """Log type of error with severity 'ERROR'."""
        exception_name = type(exception).__name__
        logger.real_logger.error(f"Error: {exception_name}")
